 s.append(Paragraph('2. Valores para copiar y comprobar',H1));s.append(tbl(['Variable','Z1 = 26 (<30)','Z2 = 52 (≥30)'],[['Alfa para Excel/TXT','14 (representa 14.5°)','14 (representa 14.5°)'],['De','112.00','216.00'],['Dp','104.00','208.00'],['Ct · K=0.96815','100.69','201.38'],['Di','94.66','198.00'],['Par / Pitch','12.57','12.57'],['Delta','3.46°','1.73°'],['R1','7.28','26.00'],['R2 / R3','22.88 / 34.32','No aplica'],['r / Acara','1.20 / 16.00','1.20 / 16.00'],['A / D','4.00 / 5.00','4.00 / 5.00'],['Chaflán','2.16','4.24'],['Plano de flexión De/2','56.00','108.00']],[43*mm,65*mm,66*mm]))
 s.append(box('Chequeo de rama','Z1=26 es <b>menor que 30</b>; usá el TXT -30. Z2=52 es <b>mayor o igual que 30</b>; usá el TXT +30. Para exactamente 30 también se usa +30.',BLUE,colors.HexColor('#EAF3F8')));s.append(PageBreak())
 s.append(Paragraph('3. Ecuaciones: hacelo antes de dibujar',H1));s.append(steps([(1,'Abrí una pieza nueva. Herramientas → Ecuaciones. Para Z1, abrí <b>Equations -30.txt</b>; copiá/pegá todo.','Lista completa de variables.','No escribas fórmulas a mano si podés copiar el TXT.'),(2,'Editá <b>solo las primeras tres</b>: N=26, Alfa=14, M=4. Aceptá.','No hay ecuaciones rojas; valores coinciden con tabla anterior.','14 equivale a 14.5° según la plantilla. No pongas 14.5.'),(3,'Repetí en una segunda pieza con <b>Engranaje +30 (2).txt</b>: N=52, Alfa=14, M=4.','Z2 tiene un solo R1, además P/4 y Dist_Plan.','Nunca copies R2/R3 en Z2.')]))
