 s.append(Paragraph('6. Tallar y repetir Z1',H1));s.append(steps([(10,'Nuevo croquis sobre cara frontal. Convertir entidades de De, Di y los tres arcos; línea vertical como construcción. Aplicá Simetría de los tres arcos respecto a la vertical.','Dos flancos simétricos.','No borres TRAZADO_DIAMETROS_Z1: solo ocultalo después.'),(11,'Recortá los sobrantes de De/Di para dejar <b>un único contorno cerrado</b> de espacio entre dientes. Operaciones → Extruir corte → Por todo.','Un solo hueco recto entre dientes.','Si el área no queda sombreada, hay una entidad abierta o duplicada.'),(12,'Redondeo del pie de diente <b>r=1.20</b>. Operaciones → Matriz circular: eje central, separación igual, <b>26 instancias</b>; incluir Corte extruido y Redondeo.','26 dientes/espacios completos; sin errores de reconstrucción.','Si falta una operación, edita la matriz y añádela en “Operaciones para matriz”.')]))
 s.append(fig(16,'Profesor: selección del corte extruido y geometría constructiva del perfil.'));s.append(fig(17,'Profesor: redondeo del pie y matriz circular; número de instancias = número de dientes.'));s.append(PageBreak())
