 s.append(steps([(16,'Para Z1: Insertar → Geometría de referencia → Plano. Seleccioná <b>Plano Planta</b>, paralelo a distancia <b>De/2 = 56 mm</b>. Para Z2 repetí con <b>108 mm</b>.','Plano nuevo paralelo y visible por fuera del engranaje.','No selecciones una arista móvil como referencia del plano.'),(17,'Sobre Plano1: Croquis → línea constructiva que forme <b>25°</b> con la referencia horizontal/vertical indicada. Debe terminar hacia la parte posterior del engranaje.','Línea de 25° visible junto al engranaje.','Usá el valor absoluto 25° en ambos; el sentido opuesto se da al flexionar.'),(18,'En la cara posterior, croquis nuevo: línea desde centro del engranaje hasta el extremo de la línea de 25° del Plano1. Vista lateral → Medir ángulo entre ambas líneas.','Obtenés un ángulo real medido para esa pieza.','No copies un ángulo de otro ejemplo; depende de De y de tu espesor.'),(19,'Vista isométrica → Insertar → Operaciones → <b>Flexionar</b>. Elegí <b>Torsión</b>; seleccioná la región/cuerpo que pide SolidWorks y escribí el ángulo que acabás de medir. Para Z2 usá el <b>signo contrario</b> al de Z1.','Dientes inclinados y cuerpo reconstruido.','Si falla, suprimí temporalmente chaflanes, revisá plano/línea y seleccioná el cuerpo entero.')]))
 s.append(fig(39,'PDF del profesor: Plano1 paralelo a Planta a distancia De/2 y línea de ángulo de hélice.'));s.append(fig(42,'PDF del profesor: Insertar → Operaciones → Flexionar, opción Torsión y ángulo medido.'));s.append(PageBreak())
